#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_camX;
uniform float amzp_camY;
uniform float amzp_camZ;
uniform float3 amzp_rotDeg;
uniform float amzp_zSpeed;
uniform float amzp_autoBlur;
uniform float amzp_blurFactor;
uniform float amzp_rotBlurSpeed;
uniform float amzp_manualTrail;
uniform float amzp_brightness;
uniform float amzp_particleSize;
uniform float amzp_particleCount;
layout(color) uniform half4 amzp_colorA;
layout(color) uniform half4 amzp_colorB;
uniform float amzp_alpha;
uniform float3 amzp_sysRotDeg;
uniform float amzp_sysRotSpeedX;
uniform float amzp_sysRotSpeedY;
uniform float amzp_sysRotSpeedZ;




    float Random(float x){
      return fract(sin(x * 123.456) * 23.4567 + sin(x * 345.678) * 45.6789 + sin(x * 456.789) * 56.789);
    }

    float3 RotateX(float3 v, float a){ float s=sin(a), c=cos(a); return float3(v.x, c*v.y + s*v.z, -s*v.y + c*v.z); }
    float3 RotateY(float3 v, float a){ float s=sin(a), c=cos(a); return float3(c*v.x + s*v.z, v.y, -s*v.x + c*v.z); }
    float3 RotateZ(float3 v, float a){ float s=sin(a), c=cos(a); return float3(c*v.x + s*v.y, -s*v.x + c*v.y, v.z); }


    const float fSteps = 121.0;
    const float fMinDist = 0.8;
    const float fMaxDist = 5.0;
    const float fRepeatMin = 1.0;
    const float fRepeatMax = 2.0;
    const float fDepthFade = 0.8;

    float3 GetParticlePos(float3 vRayDir, float fZPos, float fSeed){
      float fAngle = atan(vRayDir.x, vRayDir.y);
      float fAngleFraction = fract(fAngle / (6.28318530718));
      float fSegment = floor(fAngleFraction * fSteps + fSeed) + 0.5 - fSeed;
      float fParticleAngle = fSegment / fSteps * (6.28318530718);
      float fSegmentPos = fSegment / fSteps;
      float fRadius = fMinDist + Random(fSegmentPos + fSeed) * (fMaxDist - fMinDist);
      float tunnelZ = vRayDir.z / length(vRayDir.xy / fRadius);
      tunnelZ += fZPos;
      float fRepeat = fRepeatMin + Random(fSegmentPos + 0.1 + fSeed) * (fRepeatMax - fRepeatMin);
      float fParticleZ = (ceil(tunnelZ / fRepeat) - 0.5) * fRepeat - fZPos;
      return float3( sin(fParticleAngle) * fRadius, cos(fParticleAngle) * fRadius, fParticleZ );
    }

    float3 GetParticleColour(float3 vParticlePos, float fParticleSize, float3 vRayDir, float particleLength, float amzp_brightness){
      float2 vNormDir = normalize(vRayDir.xy);
      float d1 = dot(vParticlePos.xy, vNormDir.xy) / max(length(vRayDir.xy), 1e-5);
      float3 vClosest2d = vRayDir * d1;
      float3 vClampedPos = vParticlePos;
      vClampedPos.z = clamp(vClosest2d.z, vParticlePos.z - particleLength, vParticlePos.z + particleLength);
      float d = dot(vClampedPos, vRayDir);
      float3 vClosestPos = vRayDir * d;
      float3 vDeltaPos = vClampedPos - vClosestPos;
      float fClosestDist = length(vDeltaPos) / max(fParticleSize, 1e-5);
      float fShade = clamp(1.0 - fClosestDist, 0.0, 1.0);
      fShade = fShade * exp2(-d * fDepthFade) * amzp_brightness;
      return float3(fShade);
    }

    float4 GetParticleEx(float3 vRayDir, float fZPos, float fSeed){
      float fAngle = atan(vRayDir.x, vRayDir.y);
      float fAngleFraction = fract(fAngle / (6.28318530718));
      float fSegment = floor(fAngleFraction * fSteps + fSeed) + 0.5 - fSeed;
      float fParticleAngle = fSegment / fSteps * (6.28318530718);
      float fSegmentPos = fSegment / fSteps;
      float fRadius = fMinDist + Random(fSegmentPos + fSeed) * (fMaxDist - fMinDist);
      float tunnelZ = vRayDir.z / length(vRayDir.xy / fRadius);
      tunnelZ += fZPos;
      float fRepeat = fRepeatMin + Random(fSegmentPos + 0.1 + fSeed) * (fRepeatMax - fRepeatMin);
      float fRing = (ceil(tunnelZ / fRepeat) - 0.5);
      float fParticleZ = fRing * fRepeat - fZPos;
      float id = floor(fSegment) + 4096.0 * floor(fRing);
      float3 amzLocal_pos = float3( sin(fParticleAngle) * fRadius, cos(fParticleAngle) * fRadius, fParticleZ );
      return float4(amzLocal_pos, id);
    }

    float3 Starfield(float3 vRayDir, float fZPos, float fSeed, float fParticleSize, float particleLength, float amzp_brightness){
      float3 sysRad = radians(amzp_sysRotDeg);
      float ax = sysRad.x + radians(amzp_sysRotSpeedX) * time;
      float ay = sysRad.y + radians(amzp_sysRotSpeedY) * time;
      float az = sysRad.z + radians(amzp_sysRotSpeedZ) * time;
      float3 vRayObj = vRayDir;
      vRayObj = RotateX(vRayObj, -ax);
      vRayObj = RotateY(vRayObj, -ay);
      vRayObj = RotateZ(vRayObj, -az);
      float4 P = GetParticleEx(vRayObj, fZPos, fSeed);
      float3 vParticlePos = P.xyz;
      float pid = P.w;
      float3 shade = GetParticleColour(vParticlePos, fParticleSize, vRayObj, particleLength, amzp_brightness);
      float h = fract(sin(pid*123.456 + fSeed*7.123) * 43758.5453);
      float3 c = (h < 0.5) ? amzp_colorA.rgb : amzp_colorB.rgb;
      return shade * c;
    }

    void amzRender(){

      float2 vScreenUV = amzScreenNorm();
      float2 vScreenPos = vScreenUV * 2.0 - 1.0;
      vScreenPos.x *= screen.zw.x / max(screen.zw.y, 1.0);

      vScreenPos += float2(amzp_camX, amzp_camY) * 0.2;

      float3 vRayDir = normalize(float3(vScreenPos, 1.0));


      float3 rotRad = radians(amzp_rotDeg);
      float rx = rotRad.x;
      float ry = rotRad.y;
      float rz = rotRad.z;
      vRayDir = RotateX(vRayDir, rx);
      vRayDir = RotateY(vRayDir, ry);
      vRayDir = RotateZ(vRayDir, rz);


      float t = time;
      float fZPos = amzp_camZ + t * amzp_zSpeed;
      float fSpeed = abs(amzp_zSpeed);


      float rotComponent = amzp_rotBlurSpeed * 0.002; 
      float particleLength = (amzp_autoBlur>0.5) ? (amzp_blurFactor * (fSpeed + rotComponent + 0.001)) : amzp_manualTrail; 


      float3 vResult = float3(0.0);


      int passes = int(clamp(float(amzp_particleCount), 1.0, 3.0));
      float fSeed = 0.0;
      for(int i=0;i<3;i++){
        if(i>=passes) break;
        vResult += Starfield(vRayDir, fZPos, fSeed, amzp_particleSize, particleLength, amzp_brightness);
        fSeed += 1.234;
      }

      float3 col = sqrt(vResult);

      float starIntensity = max(max(col.r, col.g), col.b);
      float aOut = clamp(starIntensity, 0.0, 1.0) * amzp_alpha;
      amzOutput = float4(col, aOut);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

